// Reconnect production integrations before enabling submissions.
(()=>{const message=()=>alert("This restored site is not connected to its form or payment service yet. Please use the listed email address to contact United Carriers.");document.addEventListener("submit",e=>{e.preventDefault();e.stopImmediatePropagation();message()},true);document.addEventListener("click",e=>{if(e.target.closest(".form-submit, [data-node-type=commerce-checkout-place-order-button], [data-node-type=commerce-add-to-cart-button]")){e.preventDefault();e.stopImmediatePropagation();message()}},true)})();
